using System;
using System.Collections.Generic;
using System.Drawing;
namespace Downfield {
public partial class GameForm {
 DrawnPlay draftPlay;int routeReceiver,cursorX=12,cursorZ=5;bool drawing;float designRepeat;
 void OpenDesigner(){if(game.State!=Phase.PreSnap)return;draftPlay=game.UseCustom&&game.CustomPlay!=null?game.CustomPlay.Copy():new DrawnPlay();routeReceiver=0;screen="designer";selection=0;navTime=.2f;drawing=false;}
 DrawnRoute EditRoute(){DrawnRoute r=draftPlay.Routes.Find(x=>x.Receiver==routeReceiver);if(r==null){r=new DrawnRoute();r.Receiver=routeReceiver;draftPlay.Routes.Add(r);}return r;}
 PointF DesignPoint(float x,float z){return new PointF(365+(x+26)*15,603-z*10);}
 void DesignerMouse(PointF p){if(p.X>=365&&p.X<=1145&&p.Y>=201&&p.Y<=685){float x=Math.Max(-25,Math.Min(25,(p.X-365)/15-26)),z=Math.Max(-8,Math.Min(40,(603-p.Y)/10));DrawnRoute r=EditRoute();if(r.Points.Count<20&&(r.Points.Count==0||Simulation.Distance(x,z,r.Points[r.Points.Count-1].X,r.Points[r.Points.Count-1].Z)>1.2f))r.Points.Add(new RouteNode(x,z));drawing=true;return;}foreach(MenuTarget target in menuTargets)if(target.Bounds.Contains(p)){DesignerAction(target.Index);break;}}
 void DesignerAction(int action){if(action<5){routeReceiver=action;return;}if(action==5){ApplyDraft();}else if(action==6){DrawnRoute r=EditRoute();if(r.Points.Count>0)r.Points.RemoveAt(r.Points.Count-1);}else if(action==7)EditRoute().Points.Clear();else if(action==8){franchise.SavedPlay=draftPlay.Copy();franchise.Save();}else if(action==9)draftPlay=franchise.SavedPlay.Copy();else if(action==10)Open("game");}
 void ApplyDraft(){game.CustomPlay=draftPlay.Copy();game.UseCustom=draftPlay.Routes.Exists(r=>r.Points.Count>0);game.RunPlay=false;game.Playbook=0;Open("game");}
 void TickDesigner(float dt){designRepeat-=dt;int x=input.MoveX>.5f||input.Held(Input.Right)?1:input.MoveX<-.5f||input.Held(Input.Left)?-1:0,z=input.MoveZ>.5f||input.Held(Input.Up)?1:input.MoveZ<-.5f||input.Held(Input.Down)?-1:0;if(designRepeat<=0&&(x!=0||z!=0)){cursorX=Math.Max(0,Math.Min(25,cursorX+x));cursorZ=Math.Max(0,Math.Min(20,cursorZ+z));designRepeat=.11f;}if(input.Pressed(Input.A)){DrawnRoute r=EditRoute();if(r.Points.Count<20)r.Points.Add(new RouteNode(-25+cursorX*2,cursorZ*2));}if(input.Pressed(Input.Y))routeReceiver=(routeReceiver+1)%5;if(input.Pressed(Input.X))DesignerAction(6);if(input.Pressed(Input.RB))DesignerAction(8);if(input.Pressed(Input.LB))DesignerAction(9);if(input.Pressed(Input.Start))ApplyDraft();if(input.Pressed(Input.B)||input.PausePressed)Open("game");}
 void DrawDesigner(){Rect(0,0,1280,800,Ink);TextAt("DRAW A PLAY",35,35,32,Gold);TextAt(Hint("A POINT / Y RECEIVER / X UNDO / MENU RUN","CLICK OR DRAG A ROUTE / ENTER POINT / Y RECEIVER"),35,87,12,White);Rect(365,199,780,486,Color.FromArgb(37,80,58));for(int row=0;row<21;row++)Line(365,203+row*24,1145,203+row*24,Color.FromArgb(55,104,72),1);for(int col=0;col<27;col++)Line(365+col*30,199,365+col*30,685,Color.FromArgb(55,104,72),1);Line(365,603,1145,603,Blue,3);
  for(int i=0;i<5;i++){float y=140+i*67;Rect(35,y,290,56,routeReceiver==i?Color.FromArgb(64,101,100):Color.FromArgb(38,45,62));TextAt(ReceiverIcon(i)+"  #"+game.Receiver(i).Number+" "+game.Receiver(i).Role,51,y+20,16,IconColor(i));HitArea(35,y,290,56,i);DrawnRoute route=draftPlay.Routes.Find(r=>r.Receiver==i);Player p=game.Receiver(i);PointF previous=DesignPoint(p.StartX,p.StartZ-game.Spot);Ell(previous.X-8,previous.Y-8,16,16,IconColor(i));if(route!=null)foreach(RouteNode node in route.Points){PointF next=DesignPoint(node.X,node.Z);Line(previous.X,previous.Y,next.X,next.Y,IconColor(i),3);Rect(next.X-4,next.Y-4,8,8,IconColor(i));previous=next;}}
  string[] labels={"RUN PLAY","UNDO","CLEAR ROUTE","SAVE","LOAD","BACK"};for(int i=0;i<6;i++){float x=35+(i%2)*147,y=500+i/2*69;Rect(x,y,136,58,Color.FromArgb(52,75,84));TextAt(labels[i],x+68-PixelFont.Width(labels[i],11)/2,y+22,11,i==0?Gold:White);HitArea(x,y,136,58,i+5);}PointF cursor=DesignPoint(-25+cursorX*2,cursorZ*2);Line(cursor.X-10,cursor.Y,cursor.X+10,cursor.Y,Gold,3);Line(cursor.X,cursor.Y-10,cursor.X,cursor.Y+10,Gold,3);TextAt(Hint("RB SAVE / LB LOAD / B BACK","20 POINTS PER ROUTE / SAVE STORES YOUR PLAY"),35,727,12,Mint);
 }
}
}
